    awards.push({ playerId: id, title, detail, icon });
  for (const id of state.winnerIds) add(id, 'City Champion', 'Finished with the highest fortune', 'crown');
  const categories: [keyof PlayerMetrics, string, string, PlayerAward['icon']][] = [
    ['mergesCaused', 'Deal Maker', 'Most mergers set in motion', 'merge'],
    ['chainsFounded', 'Founder', 'Most hotel chains founded', 'building'],
    ['mergerBonuses', 'Dividend Hunter', 'Most merger bonus cash earned', 'coins'],
    ['sharesBought', 'Market Maker', 'Most shares purchased', 'stocks'],
  ];
  if (getHouseRules(state).placementsPerTurn > 1 || getHouseRules(state).removalsPerTurn > 0)
    categories.push(['tilesPlaced', 'City Builder', 'Most buildings placed', 'tiles']);
