  const connection = independentConnection(state, merger.tile);
  for (const tile of connection.tiles) state.board[tile] = merger.survivor!;
  log(
    state,
    'merger',
    `${DEFINITIONS[merger.survivor!].name} now spans ${getChainSize(state, merger.survivor!)} buildings.`,
    { chain: merger.survivor! },
  );
