      assert(canRemoveTile(state, action.tile), 'Choose a tile that leaves every hotel chain intact.');
      delete state.board[action.tile];
      state.bag.push(action.tile);
      shuffle(state, state.bag);
      state.removalsThisTurn = (state.removalsThisTurn ?? 0) + 1;
      if (state.lastPlacedTile === action.tile) state.lastPlacedTile = null;
